{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(및 부적절한) 소화제",
      "start": "p3:L32",
      "end": "p3:L35"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p3:L36",
      "end": "p3:L41"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재 진압 시 착용할 보호구 및 예방조치",
      "start": "p4:L1",
      "end": "p4:L5"
    }
  ]
,
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "가. 적절한(및 부적절한) 소화제",
      "reason": "코드없음",
      "statements": [
        {
          "key": "소화제",
          "value": "분말소화제, 탄산가스, 일반 포말소화제, 분무"
        ,
          "line": "p3:L33"
        },
        {
          "key": "주의사항",
          "value": "직사주수를 사용한 소화는 피하시오."
        ,
          "line": "p3:L34"
        }
      ]
    ,
      "line": "p3:L32"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "reason": "코드없음",
      "statements": [
        {
          "value": "고인화성 액체 및 증기"
        ,
          "line": "p3:L37"
        },
        {
          "value": "눈에 심한 자극을 일으킴"
        ,
          "line": "p3:L38"
        },
        {
          "value": "삼켜서 기도로 유입되면 치명적일 수 있음"
        ,
          "line": "p3:L39"
        },
        {
          "value": "암을 일으킬 수 있음"
        ,
          "line": "p3:L40"
        },
        {
          "value": "유전적인 결함을 일으킬 수 있음"
        ,
          "line": "p3:L41"
        }
      ]
    ,
      "line": "p3:L36"
    },
    {
      "after_item": "S5_FIREFIGHT",
      "title_raw": "다. 화재 진압 시 착용할 보호구 및 예방조치",
      "reason": "코드없음",
      "statements": [
        {
          "value": "관계인 외 접근을 막고 위험 지역의 출입을 금지하시오."
        ,
          "line": "p4:L1"
        },
        {
          "value": "대규모 화재인 경우 무인방수장치를 활용하며, 여의치 않을 경우 물러나서 타도록 내버려 두시오."
        ,
          "line": "p4:L2"
        },
        {
          "value": "물질 자체 또는 연소 생성물의 흡입을 피하시오."
        ,
          "line": "p4:L3"
        },
        {
          "value": "소방서에 알리고, 화재 위치와 유해한 특징을 알려주시오."
        ,
          "line": "p4:L4"
        },
        {
          "value": "위험 없이 할 수 있다면 용기를 화재지역으로부터 이동시키시오."
        ,
          "line": "p4:L5"
        }
      ]
    ,
      "line": "p4:L1"
    }
  ]
}

